  const data = {};

  // Check accordions or result text
  const accordions = Array.from(document.querySelectorAll('.webmd-accordian, [class*="accordian"], [class*="accordion"]'));
  data.accordions = accordions.map(a => a.innerText);

  // Check initialResults from Vue if available
  const rootComp = document.querySelector('#rootApp')?._vnode?.component;
  function findChildWithProp(comp) {
    if (!comp) return null;
    if (comp.data && comp.data.initialResults !== undefined) return comp;
    if (comp.proxy && comp.proxy.initialResults !== undefined) return comp;
    if (comp.subTree) {
      const q = [comp.subTree];
      while (q.length) {
        const item = q.shift();
        if (!item) continue;
        if (item.component) {
          if (item.component.data && item.component.data.initialResults !== undefined) return item.component;
          if (item.component.proxy && item.component.proxy.initialResults !== undefined) return item.component;
          q.push(item.component.subTree);
        }
        if (Array.isArray(item.children)) {
          for (const c of item.children) {
            if (c && typeof c === 'object') q.push(c);
          }
        }
      }
    }
    return null;
  }
  const comp = findChildWithProp(rootComp);
  if (comp) {
    data.initialResults = comp.proxy.initialResults;
    data.latestPeriodDate = comp.proxy.latestPeriodDate?.toString();
    data.cycleLength = comp.proxy.cycleLength;
  }

  // Also read visible text headers in results section
  const resCards = Array.from(document.querySelectorAll('.oc-res-card, [class*="result"], [class*="acc-header"]')).map(el => el.innerText.trim()).filter(Boolean);
