      let comp = node.__vueParentComponent;
      while (comp) {
        if (comp.setupState?.latestPeriodDate !== undefined || comp.data?.latestPeriodDate !== undefined || comp.proxy?.latestPeriodDate !== undefined) {
          return comp;
        }
        comp = comp.parent;
      }
