      if (res) return res;
    }
    return null;
  }
  const comp = searchVue(app || document.body);
  if (comp) {
    return {
      found: true,
      dataKeys: Object.keys(comp.data || {}),
      proxyKeys: Object.keys(comp.proxy || {}).filter(k => !k.startsWith('$')),
      cycleLength: comp.proxy?.cycleLength,
      latestPeriodDate: comp.proxy?.latestPeriodDate
    };
  }
  return { found: false };
});
