const traverseRes = await browserjs(tabId, () => {
  const rootComp = document.querySelector('#rootApp')?._vnode?.component;
  if (!rootComp) return "No rootComp";

  function findChildWithProp(comp) {
    if (!comp) return null;
    if (comp.data && comp.data.latestPeriodDate !== undefined) return comp;
    if (comp.proxy && comp.proxy.latestPeriodDate !== undefined) return comp;
    if (comp.subTree) {
      const q = [comp.subTree];
      while (q.length) {
        const item = q.shift();
        if (!item) continue;
        if (item.component) {
          if (item.component.data && item.component.data.latestPeriodDate !== undefined) return item.component;
          if (item.component.proxy && item.component.proxy.latestPeriodDate !== undefined) return item.component;
          q.push(item.component.subTree);
        }
        if (Array.isArray(item.children)) {
          for (const c of item.children) {
            if (c && typeof c === 'object') q.push(c);
          }
        }
      }
    }
    return null;
  }

  const target = findChildWithProp(rootComp);
  if (!target) return "Not found in subtree";

  return {
    found: true,
    data: {
      cycleLength: target.proxy.cycleLength,
      latestPeriodDate: target.proxy.latestPeriodDate,
      disabledDatesObj: target.proxy.disabledDatesObj
    }
  };
});
console.log(traverseRes);

